import { FocusContext, useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import type { Track } from '@mfp/core';
import { FocusButton } from '../components/FocusButton.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapVar } from '../theme/gap.js';

export interface AudioSubtitlePanelProps {
  audio: Track[];
  text: Track[];
  activeAudioId?: string;
  activeTextId?: string | null;
  onAudio: (id: string) => void;
  onText: (id: string | null) => void;
  onClose: () => void;
}

/** Painel de faixas de áudio e legenda (tela 13). Faixas vêm do container. */
export function AudioSubtitlePanel({
  audio,
  text,
  activeAudioId,
  activeTextId,
  onAudio,
  onText,
  onClose,
}: AudioSubtitlePanelProps) {
  const { ref, focusKey } = useFocusable({
    focusKey: 'audiosub',
    trackChildren: true,
    saveLastFocusedChild: true,
  });

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          position: 'absolute',
          top: 0,
          right: 0,
          bottom: 0,
          width: '24rem',
          padding: '2rem',
          background: 'var(--bg-scrim)',
          display: 'flex',
          flexDirection: 'column',
          overflow: 'auto',
          ...gapVar('0.6rem'),
        }}
      >
        <h3>{t('player.audioSubtitles')}</h3>

        <strong style={{ color: 'var(--text-secondary)' }}>
          {t('player.audioLabel')}
        </strong>
        {audio.length === 0 && <span style={{ color: 'var(--text-disabled)' }}>—</span>}
        {audio.map((tr) => (
          <FocusButton
            key={tr.id}
            focusKey={`audiosub-a-${tr.id}`}
            primary={tr.id === activeAudioId}
            onPress={() => onAudio(tr.id)}
          >
            {tr.label}
          </FocusButton>
        ))}

        <strong style={{ color: 'var(--text-secondary)', marginTop: '0.8rem' }}>
          {t('player.subtitlesLabel')}
        </strong>
        <FocusButton
          focusKey="audiosub-t-off"
          primary={activeTextId == null}
          onPress={() => onText(null)}
        >
          {t('player.subtitlesOff')}
        </FocusButton>
        {text.map((tr) => (
          <FocusButton
            key={tr.id}
            focusKey={`audiosub-t-${tr.id}`}
            primary={tr.id === activeTextId}
            onPress={() => onText(tr.id)}
          >
            {tr.label}
          </FocusButton>
        ))}

        <FocusButton focusKey="audiosub-close" onPress={onClose}>
          {t('common.close')}
        </FocusButton>
      </div>
    </FocusContext.Provider>
  );
}
