import type { BufferConfig } from './types.js';

// playback-design.md §11. Cada PlatformAdapter pode sobrepor campos (ex.: webOS 4
// → stall.* +50%).

export type BufferPreset = 'curto' | 'medio' | 'longo';

export interface PlaybackConfig {
  openTimeoutSecs: number;
  reconnectAfterPlayingTimeoutSecs: number;
  stall: {
    nudgeAfterSecs: number;
    livePlaySecs: number;
    vodPlaySecs: number;
    liveBufferSecs: number;
    vodBufferSecs: number;
  };
  /** backoff = random(0,1) * min(capSecs, baseSecs * 2^(attempt-1)) */
  backoff: { baseSecs: number; capSecs: number };
  maxAttempts: { live: number; vod: number };
  slowRetry: { intervalSecs: number; forSecs: number };
  progressSaveEverySecs: number;
  resumeWindow: { minSecs: number; maxPct: number };
  bufferPresets: Record<
    BufferPreset,
    Omit<BufferConfig, 'maxVideoHeight' | 'liveEdgeSegments'>
  >;
  liveEdgeSegments: number;
}

export const DEFAULT_PLAYBACK_CONFIG: PlaybackConfig = {
  openTimeoutSecs: 12,
  reconnectAfterPlayingTimeoutSecs: 12,
  stall: {
    nudgeAfterSecs: 3,
    livePlaySecs: 8,
    vodPlaySecs: 12,
    liveBufferSecs: 15,
    vodBufferSecs: 25,
  },
  backoff: { baseSecs: 1, capSecs: 10 },
  maxAttempts: { live: 6, vod: 4 },
  slowRetry: { intervalSecs: 30, forSecs: 300 },
  progressSaveEverySecs: 10,
  resumeWindow: { minSecs: 5, maxPct: 0.95 },
  bufferPresets: {
    curto: {
      targetSecs: 10,
      forPlaybackSecs: 1.0,
      forResumeAfterRebufferSecs: 2.5,
      backBufferSecs: 12,
    },
    medio: {
      targetSecs: 30,
      forPlaybackSecs: 2.5,
      forResumeAfterRebufferSecs: 5.0,
      backBufferSecs: 12,
    },
    longo: {
      targetSecs: 50,
      forPlaybackSecs: 3.0,
      forResumeAfterRebufferSecs: 7.0,
      backBufferSecs: 12,
    },
  },
  liveEdgeSegments: 3,
};

/** Monta o BufferConfig final a partir do preset + tetos opcionais. */
export function resolveBuffer(
  cfg: PlaybackConfig,
  preset: BufferPreset,
  extra?: { maxVideoHeight?: number; liveEdgeSegments?: number },
): BufferConfig {
  return {
    ...cfg.bufferPresets[preset],
    liveEdgeSegments: extra?.liveEdgeSegments ?? cfg.liveEdgeSegments,
    ...(extra?.maxVideoHeight != null ? { maxVideoHeight: extra.maxVideoHeight } : {}),
  };
}

/** Atraso do backoff com full jitter (fórmula AWS). `rand` injetável para teste. */
export function backoffDelaySecs(
  cfg: PlaybackConfig,
  attempt: number,
  rand: () => number = Math.random,
): number {
  const ceil = Math.min(cfg.backoff.capSecs, cfg.backoff.baseSecs * 2 ** (attempt - 1));
  return rand() * ceil;
}
