import { useCallback, useEffect, useRef, useState } from 'react';
import {
  DEFAULT_PLAYBACK_CONFIG,
  PlaybackController,
  resolveBuffer,
  systemClock,
  type BufferPreset,
  type PlaybackSnapshot,
  type StreamKindPB,
  type Track,
  type VideoFit,
  type VideoPlayer,
} from '@mfp/core';
import type { PlatformAdapter } from '@mfp/platform';

export interface UsePlaybackArgs {
  adapter: PlatformAdapter;
  kind: StreamKindPB;
  /** rebuild da URL de stream a cada tentativa (RF-60). */
  resolveUrl: (ctx: { reauth: boolean; attempt: number }) => Promise<string>;
  startAtSecs?: number;
  bufferPreset?: BufferPreset;
  /** Teto de resolução vertical em px (PERF-26). 0 = sem teto. Aplica no próximo load. */
  maxVideoHeight?: number;
  /**
   * Segura o `open()` real sem deixar de montar o player/controller — usado
   * pelo check de decodificação (Player.tsx) enquanto ele ainda não decidiu
   * se o título é seguro para tentar.
   */
  held?: boolean;
  onProgress?: (p: {
    positionSecs: number;
    durationSecs: number;
    completed: boolean;
  }) => void;
}

const INITIAL: PlaybackSnapshot = {
  state: 'IDLE',
  attempt: 0,
  slowMode: false,
  error: null,
  positionSecs: 0,
  durationSecs: 0,
  paused: false,
  isLive: true,
  waitingForNetwork: false,
};

/**
 * Liga um `PlaybackController` do core a um `VideoPlayer` da plataforma montado num
 * `<div>`. A UI só observa o `snapshot` e chama os controles.
 */
export function usePlayback(args: UsePlaybackArgs) {
  const {
    adapter,
    kind,
    resolveUrl,
    startAtSecs,
    bufferPreset = 'medio',
    maxVideoHeight = 0,
    held = false,
    onProgress,
  } = args;
  const mountRef = useRef<HTMLDivElement>(null);
  const ctrlRef = useRef<PlaybackController | null>(null);
  const playerRef = useRef<VideoPlayer | null>(null);
  const [snapshot, setSnapshot] = useState<PlaybackSnapshot>(INITIAL);
  const [hasVideoFit, setHasVideoFit] = useState(false);
  const [tracks, setTracks] = useState<{ audio: Track[]; text: Track[] }>({
    audio: [],
    text: [],
  });

  // refs para não recriar o controller quando só o callback muda
  const resolveRef = useRef(resolveUrl);
  const progressRef = useRef(onProgress);
  useEffect(() => {
    resolveRef.current = resolveUrl;
    progressRef.current = onProgress;
  }, [resolveUrl, onProgress]);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    const player = adapter.createVideoPlayer(mount);
    playerRef.current = player;
    setHasVideoFit(!!player.setVideoFit);
    let online = true;
    const onlineSubs = new Set<() => void>();
    const netOff = adapter.onVisibilityChange(() => {});
    const refreshTracks = () =>
      setTracks({ audio: player.getAudioTracks(), text: player.getTextTracks() });
    const offReady = player.on('playing', refreshTracks);

    const ctrl = new PlaybackController({
      player,
      clock: systemClock,
      isOnline: () => online,
      onOnline: (cb) => {
        onlineSubs.add(cb);
        return () => onlineSubs.delete(cb);
      },
      resolveUrl: (ctx) => resolveRef.current(ctx),
    });
    ctrlRef.current = ctrl;

    const offSnap = ctrl.events.on('snapshot', setSnapshot);
    const offProg = ctrl.events.on('progress', (p) => progressRef.current?.(p));

    const onOnline = () => {
      online = true;
      onlineSubs.forEach((cb) => cb());
    };
    const onOffline = () => {
      online = false;
    };
    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    // `held`: check de capacidade de decodificação ainda em andamento (ou
    // recusou o título — ver Player.tsx). O player/controller já existem
    // (troca de foco/overlay não depende disso), só o `open()` de verdade
    // espera a liberação.
    if (!held) {
      void ctrl.open({
        kind,
        startAtSecs,
        buffer: resolveBuffer(DEFAULT_PLAYBACK_CONFIG, bufferPreset, { maxVideoHeight }),
      });
    }

    return () => {
      offSnap();
      offProg();
      offReady();
      netOff();
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
      ctrl.destroy();
      player.destroy();
      ctrlRef.current = null;
      playerRef.current = null;
    };
    // recria só quando a fonte lógica muda (`held` inclui a liberação do
    // check de decodificação — rara, só uma vez por título)
  }, [adapter, kind, startAtSecs, bufferPreset, maxVideoHeight, held]);

  /** Reabre a mesma sessão — usado no zapping (a URL vem do resolveUrl atualizado). */
  const reload = useCallback(
    (opts?: { startAtSecs?: number }) => {
      void ctrlRef.current?.open({
        kind,
        startAtSecs: opts?.startAtSecs,
        buffer: resolveBuffer(DEFAULT_PLAYBACK_CONFIG, bufferPreset, { maxVideoHeight }),
      });
    },
    [kind, bufferPreset, maxVideoHeight],
  );

  return {
    mountRef,
    snapshot,
    tracks,
    play: () => ctrlRef.current?.play(),
    pause: () => ctrlRef.current?.pause(),
    stop: () => ctrlRef.current?.stop(),
    seek: (s: number) => ctrlRef.current?.seek(s),
    retry: () => ctrlRef.current?.retry(),
    reload,
    setAudioTrack: (id: string) => playerRef.current?.setAudioTrack(id),
    setTextTrack: (id: string | null) => playerRef.current?.setTextTrack(id),
    /** D-21. `hasVideoFit` diz se a plataforma implementa (senão o botão some). */
    hasVideoFit,
    setVideoFit: (mode: VideoFit) => playerRef.current?.setVideoFit?.(mode),
  };
}
