import { useCallback, useEffect, useRef, useState } from 'react';
import { setFocus } from '@noriginmedia/norigin-spatial-navigation';
import type { StreamKindPB, Track, VideoFit } from '@mfp/core';
import type { PlatformAdapter } from '@mfp/platform';
import { PlayerShell } from '../player/PlayerShell.js';
import { usePlayback } from '../player/usePlayback.js';
import { tetoResolucaoPx } from '../player/resolution.js';
import { AudioSubtitlePanel } from '../player/AudioSubtitlePanel.js';
import { ChannelListOverlay } from '../player/ChannelListOverlay.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useLists } from '../state/lists.js';
import { useNavigation } from '../nav/navigationStack.js';
import { useNowPlaying, type QueueItem } from '../state/nowPlaying.js';
import { useEpgNow } from '../state/nowNext.js';
import { useLive } from '../state/live.js';
import { useFavorites } from '../state/favorites.js';
import { useSettings } from '../state/settings.js';
import { DEFAULT_PROFILE } from '../state/catalog.js';
import { ErrorScreen } from '../components/states.js';
import { t } from '../i18n/index.js';

export interface PlayerParams {
  kind: StreamKindPB;
  streamId: string;
  ext?: string;
  title: string;
  subtitle?: string;
  startAtSecs?: string;
  /** Pôster do item, gravado no progresso para a trilha "Continuar assistindo". */
  poster?: string;
  /** Série de origem, quando é um episódio. */
  seriesId?: string;
}

interface CurrentItem {
  id: string;
  title: string;
  subtitle?: string;
  ext?: string;
}

/** Idioma de uma faixa — o rótulo serve de chave quando o engine não informa. */
const idiomaDe = (faixas: Track[], id: string | null): string =>
  faixas.find((f) => f.id === id)?.language ??
  faixas.find((f) => f.id === id)?.label ??
  '';

/** Ordem em que a tecla Azul / o botão do OSD ciclam o formato (D-21). */
const ORDEM_FIT: VideoFit[] = ['original', 'fill', '16:9', '4:3'];

/** `live` ⇄ `''` — os dois formatos de path de canal que os painéis usam. */
const alternar = (segmento: string | undefined): string =>
  (segmento ?? 'live') === 'live' ? '' : 'live';

/** Faixa que casa com o idioma guardado; `undefined` se não há preferência. */
function acharPorIdioma(faixas: Track[], idioma: string): Track | undefined {
  if (!idioma || idioma === 'off') return undefined;
  return (
    faixas.find((f) => f.language === idioma) ?? faixas.find((f) => f.label === idioma)
  );
}

export function Player({
  adapter,
  params,
}: Readonly<{ adapter: PlatformAdapter; params: PlayerParams }>) {
  const rt = useRuntime();
  const pop = useNavigation((s) => s.pop);
  const activeListId = useLists((s) => s.activeListId);
  const getPassword = useLists((s) => s.getPassword);
  const definirSegmentoLive = useLists((s) => s.definirSegmentoLive);
  const lists = useLists((s) => s.lists);
  const list = lists.find((l) => l.id === activeListId);
  const step = useNowPlaying((s) => s.step);
  const goto = useNowPlaying((s) => s.goto);
  const fila = useNowPlaying((s) => s.items);
  const filaIndice = useNowPlaying((s) => s.index);
  const rememberChannel = useLive((s) => s.rememberChannel);
  // Seletores estreitos (PERF-11) — ver o comentário equivalente em MovieDetail.tsx
  const isFav = useFavorites((s) => s.isFav);
  const alternarFavorito = useFavorites((s) => s.toggle);
  const carregarFavoritos = useFavorites((s) => s.load);
  const _favKeys = useFavorites((s) => s.keys);
  const audioLang = useSettings((s) => s.audioLang);
  const subtitleLang = useSettings((s) => s.subtitleLang);
  const atualizarPrefs = useSettings((s) => s.update);
  const buffer = useSettings((s) => s.buffer);
  const videoFit = useSettings((s) => s.videoFit);
  const maxRes = useSettings((s) => s.maxVideoHeight);
  const autoplayNext = useSettings((s) => s.autoplayNext);

  const [item, setItem] = useState<CurrentItem>({
    id: params.streamId,
    title: params.title,
    subtitle: params.subtitle,
    ext: params.ext,
  });
  const [audioOpen, setAudioOpen] = useState(false);
  const [canaisAbertos, setCanaisAbertos] = useState(false);
  // `undefined` = ninguém escolheu nada neste título; aí vale a preferência
  // guardada (ver `faixaPreferida*`). Em `activeText`, `null` é escolha real:
  // legenda desligada.
  const [activeAudio, setActiveAudio] = useState<string | undefined>();
  const [activeText, setActiveText] = useState<string | null | undefined>();
  // id do item para o qual o usuário cancelou o banner de próximo episódio —
  // reseta sozinho ao trocar de episódio, já que a comparação é por `item.id`.
  const [proximoDispensadoPara, setProximoDispensadoPara] = useState<string | null>(null);
  const itemRef = useRef(item);
  useEffect(() => {
    itemRef.current = item;
  }, [item]);

  /**
   * Caminho alternativo do canal ao vivo: alguns painéis servem em
   * `/{user}/{pass}/{id}`, sem o `live/`. Não dá para descobrir pelo
   * `server_info` — quem descobre é o 404 da primeira tentativa.
   */
  const [segundoCaminho, setSegundoCaminho] = useState(false);

  const resolveUrl = useCallback(async () => {
    if (!list) throw new Error('sem lista ativa');
    const password = (await getPassword(rt, list.id)) ?? '';
    const provider = rt.makeProvider(
      segundoCaminho
        ? { ...list, livePathSegment: alternar(list.livePathSegment) }
        : list,
      password,
    );
    const cur = itemRef.current;
    const seg = params.kind === 'live' ? 'live' : 'movie';
    return provider.buildStreamUrl(seg, cur.id, cur.ext);
  }, [rt, list, getPassword, params.kind, segundoCaminho]);

  const startAtSecs = params.startAtSecs ? Number(params.startAtSecs) : undefined;

  // Vetar ANTES de tentar um título que o decoder do aparelho recusa de cara
  // (achado real, spec 002/RF-11: HEVC 10-bit/HDR num aparelho de entrada
  // trava em DECODE/InsufficientResources — sem isto o usuário só descobre
  // depois de esperar o player tentar e falhar). O nome já sinaliza o perfil
  // pesado (mesma convenção "qualidade no nome" documentada no
  // panel-findings.md); `null` = ainda checando, `true` = recusado.
  const tituloHevc10Bit = /4k|uhd/i.test(item.title) && /hdr|hevc|h\.?265/i.test(item.title);
  // Só vale checar se a plataforma sabe responder — sem isto, "checando" ficaria
  // pendurado pra sempre nas plataformas sem `supportsHevc10Bit` (web/webOS/Tizen
  // por ora). Decidido já no estado inicial: nada de `setState` síncrono dentro
  // do efeito abaixo pra esse caso.
  const podeChecar = tituloHevc10Bit && !!adapter.supportsHevc10Bit;
  const [decodeBloqueado, setDecodeBloqueado] = useState<boolean | null>(
    podeChecar ? null : false,
  );
  useEffect(() => {
    if (!podeChecar) return;
    let cancelado = false;
    adapter
      .supportsHevc10Bit!()
      .then((suporta) => {
        if (!cancelado) setDecodeBloqueado(!suporta);
      })
      .catch(() => {
        if (!cancelado) setDecodeBloqueado(false);
      });
    return () => {
      cancelado = true;
    };
    // roda uma vez por título (item.id muda em série/próximo episódio)
  }, [adapter, item.id, podeChecar]);

  // Orçamento do RF-68 (spec 002): OK→primeiro frame (RP-3 live / RP-4 vod).
  // Ponto único de instrumentação — o custo real é rede + decoder, não a troca
  // de rota que trouxe até aqui. `zap()` reabre o par a cada troca de canal.
  const marcaInicio = params.kind === 'live' ? 'zap:keydown' : 'vod:open';
  const marcaFrame = params.kind === 'live' ? 'zap:firstFrame' : 'vod:firstFrame';
  const aguardandoFrame = useRef(true);
  useEffect(() => {
    rt.perf.marcar(marcaInicio, { origem: 'inicial' });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const pb = usePlayback({
    adapter,
    kind: params.kind,
    resolveUrl,
    startAtSecs,
    held: decodeBloqueado !== false,
    // RF-61: o preset escolhido em Configurações precisa chegar ao engine —
    // sem isto, "Curto/Médio/Longo" mudava o texto na tela e mais nada.
    bufferPreset: buffer,
    // PERF-26: teto de resolução resolvido a partir do ajuste (auto → tela)
    maxVideoHeight: tetoResolucaoPx(maxRes),
    onProgress: (p) => {
      if (params.kind !== 'vod' || !list) return;
      void rt.db.progress.put({
        profileId: DEFAULT_PROFILE,
        listId: list.id,
        key: `movie:${itemRef.current.id}`,
        kind: 'movie',
        id: itemRef.current.id,
        positionSecs: p.positionSecs,
        durationSecs: p.durationSecs,
        updatedAt: Date.now(),
        completed: p.completed,
        // cópia para a Home: episódio não está em nenhuma tabela do catálogo
        title: itemRef.current.title,
        ...(params.poster ? { poster: params.poster } : {}),
        ...(params.seriesId ? { seriesId: params.seriesId } : {}),
      });
    },
  });

  // primeiro frame: fecha o par aberto no mount / em `abrir()` (spec 002)
  useEffect(() => {
    if (pb.snapshot.state === 'PLAYING' && aguardandoFrame.current) {
      aguardandoFrame.current = false;
      rt.perf.marcar(marcaFrame);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pb.snapshot.state]);

  // lembra o último canal ao vivo (RF: retomar último canal)
  useEffect(() => {
    if (params.kind === 'live' && list) void rememberChannel(rt, list.id, item.id);
  }, [params.kind, list, rt, rememberChannel, item.id]);

  // Mantém a tela acesa enquanto a tela de player está montada — achado real
  // na Smart TV Pro: assistindo sem tocar no controle, o Android TV entrava
  // no protetor de tela porque nada avisava o sistema que havia mídia ativa.
  // Liga ao entrar no player, desliga ao sair (troca de canal/episódio não
  // desmonta esta tela, então não pisca a cada zap).
  useEffect(() => {
    adapter.setKeepScreenOn?.(true);
    return () => adapter.setKeepScreenOn?.(false);
  }, [adapter]);

  // favoritos do perfil, para o botão do player saber em que estado está
  useEffect(() => {
    if (list) void carregarFavoritos(rt, list.id);
  }, [rt, list, carregarFavoritos]);

  // D-21: empurra o formato de exibição guardado para o engine. O plugin nativo
  // e o player do dev reaplicam o modo a cada `load()`, então basta empurrar
  // quando a preferência muda e assim que a plataforma expõe o suporte.
  useEffect(() => {
    if (pb.hasVideoFit) pb.setVideoFit(videoFit);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [videoFit, pb.hasVideoFit]);

  // Guia do canal ao vivo (D-22) — programa no ar + a seguir, do EPG local.
  const epgAoVivo = useEpgNow(
    list?.id ?? '',
    params.kind === 'live' ? item.id : undefined,
  );

  const ciclarFormato = () => {
    const prox =
      ORDEM_FIT[(ORDEM_FIT.indexOf(videoFit) + 1) % ORDEM_FIT.length] ?? 'original';
    pb.setVideoFit(prox);
    void atualizarPrefs(rt, { videoFit: prox });
  };

  // Idioma lembrado do título anterior: as faixas só existem depois que o
  // engine abre o stream, então isto roda quando `pb.tracks` muda — uma vez por
  // título. Só chama o engine; o destaque no painel sai do valor derivado
  // abaixo, para não precisar de `setState` dentro do efeito.
  const faixaPreferidaAudio = acharPorIdioma(pb.tracks.audio, audioLang);
  const faixaPreferidaTexto =
    subtitleLang === 'off' ? undefined : acharPorIdioma(pb.tracks.text, subtitleLang);
  useEffect(() => {
    if (faixaPreferidaAudio) pb.setAudioTrack(faixaPreferidaAudio.id);
    if (subtitleLang) pb.setTextTrack(faixaPreferidaTexto?.id ?? null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [faixaPreferidaAudio?.id, faixaPreferidaTexto?.id, subtitleLang]);

  // RF-62: em segundo plano o canal ao vivo **para** — ninguém está vendo, e o
  // painel conta conexões simultâneas (`max_connections`); segurar o stream
  // aberto pode barrar a próxima abertura. VOD só pausa, para voltar de onde
  // parou. Ao voltar para o primeiro plano, o live reabre no ao vivo.
  const pbRef = useRef(pb);
  useEffect(() => {
    pbRef.current = pb;
  });
  useEffect(() => {
    return adapter.onVisibilityChange((visivel) => {
      if (visivel) {
        if (params.kind === 'live') pbRef.current.reload();
        return;
      }
      if (params.kind === 'live') pbRef.current.stop();
      else pbRef.current.pause();
    });
  }, [adapter, params.kind]);

  const abrir = (next: QueueItem | null, startAtSecs?: number) => {
    if (!next) return false;
    // novo par de medição: início agora, `marcaFrame` no próximo PLAYING (spec 002)
    aguardandoFrame.current = true;
    rt.perf.marcar(marcaInicio, { origem: 'troca' });
    setItem({ id: next.id, title: next.title, subtitle: next.subtitle, ext: next.ext });
    // resolveUrl já lê itemRef; força a reabertura no próximo tick
    setTimeout(() => pb.reload({ startAtSecs }), 0);
    return true;
  };

  const zap = (delta: number, startAtSecs?: number) => abrir(step(delta), startAtSecs);

  // BACK: fecha o overlay aberto, senão sai do player. Estável (o `PlayerShell`
  // registra na pilha de BACK, que churna à toa se a identidade muda a cada
  // render — e este componente re-renderiza a cada segundo pela posição).
  const canaisRef = useRef(canaisAbertos);
  const audioRef = useRef(audioOpen);
  useEffect(() => {
    canaisRef.current = canaisAbertos;
    audioRef.current = audioOpen;
  });
  const sair = useCallback(() => {
    if (canaisRef.current) {
      setCanaisAbertos(false);
      setFocus('player-playpause');
      return;
    }
    if (audioRef.current) {
      setAudioOpen(false);
      setFocus('player-playpause');
      return;
    }
    pbRef.current.stop();
    pop();
  }, [pop]);

  /** Salto direto — da lista sobreposta ou do número digitado no controle. */
  const irParaIndice = (indice: number) => {
    setCanaisAbertos(false);
    setFocus('player-playpause');
    abrir(goto(indice));
  };

  // 404 no canal ao vivo pode ser canal fora do ar OU path errado — os dois
  // respondem igual (ver panel-findings §Segmento live). Na primeira vez,
  // tenta o outro caminho antes de desistir; se tocar, o segmento aprendido
  // fica gravado na lista e as próximas aberturas já nascem certas.
  useEffect(() => {
    if (params.kind !== 'live' || segundoCaminho) return;
    if (pb.snapshot.state !== 'FAILED' || pb.snapshot.error?.code !== 'HTTP_404') return;
    const id = window.setTimeout(() => setSegundoCaminho(true), 0);
    return () => window.clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pb.snapshot.state, pb.snapshot.error?.code, params.kind, segundoCaminho]);

  // A retentativa vai num efeito separado, depois do commit que trocou o
  // caminho: o `usePlayback` guarda o `resolveUrl` num ref atualizado por
  // efeito, e chamar `retry()` no mesmo tick pegaria a URL antiga.
  useEffect(() => {
    if (!segundoCaminho) return;
    const id = window.setTimeout(() => pbRef.current.retry(), 0);
    return () => window.clearTimeout(id);
  }, [segundoCaminho]);

  useEffect(() => {
    if (!segundoCaminho || !list || pb.snapshot.state !== 'PLAYING') return;
    void definirSegmentoLive(rt, list.id, alternar(list.livePathSegment));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [segundoCaminho, pb.snapshot.state]);

  // Banner de próximo episódio (últimos 15s do VOD, quando há um item
  // seguinte na fila — mesmo padrão XCIPTV/Netflix): mostra o título a
  // seguir com contagem regressiva e dois botões, "Próximo episódio" (avança
  // na hora) e "Cancelar" (só esconde o banner para ESTE episódio).
  const proximoItem = params.kind === 'vod' ? (fila[filaIndice + 1] ?? null) : null;
  const restanteSecs =
    pb.snapshot.durationSecs > 0
      ? pb.snapshot.durationSecs - pb.snapshot.positionSecs
      : Number.POSITIVE_INFINITY;
  const dispensadoNesteItem = proximoDispensadoPara === item.id;
  const mostrarBannerProximo =
    !!proximoItem && !dispensadoNesteItem && restanteSecs <= 15;

  // Auto-avanço (RF61 / settings.autoplayNext): só dispara se o usuário não
  // cancelou o banner NESTE episódio e a preferência estiver ligada — antes
  // disto, o app sempre avançava sozinho ao terminar, ignorando o ajuste em
  // Configurações (que existia mas nunca era lido aqui).
  useEffect(() => {
    if (params.kind !== 'vod' || !autoplayNext || !proximoItem || dispensadoNesteItem)
      return;
    const terminou = pb.snapshot.state === 'ENDED' || restanteSecs <= 0;
    if (!terminou) return;
    const id = window.setTimeout(() => zap(1), 0);
    return () => window.clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pb.snapshot.state, restanteSecs, autoplayNext, proximoItem, dispensadoNesteItem]);

  // `useFocusGuard` (ActiveList) só conhece 'player-playpause' pra esta rota —
  // não existe enquanto esta tela substitui o PlayerShell, então o foco
  // precisa vir explícito aqui (mesmo padrão do `setFocus` no mount do
  // PlayerShell).
  useEffect(() => {
    if (decodeBloqueado) setFocus('error-retry');
  }, [decodeBloqueado]);

  if (decodeBloqueado) {
    return (
      <main style={{ padding: 'var(--safe-y) var(--safe-x)' }}>
        <ErrorScreen
          title={t('player.decodeUnsupportedTitle')}
          body={t('player.decodeUnsupportedBody')}
          code="DECODE"
          onRetry={() => setDecodeBloqueado(false)}
          retryLabel={t('player.tryAnyway')}
        />
      </main>
    );
  }

  return (
    <PlayerShell
      adapter={adapter}
      title={item.title}
      subtitle={item.subtitle}
      mountRef={pb.mountRef}
      snapshot={pb.snapshot}
      onPlayPause={() =>
        pb.snapshot.state === 'PLAYING' && !pb.snapshot.paused ? pb.pause() : pb.play()
      }
      onSeekRelative={(d) => pb.seek(pb.snapshot.positionSecs + d)}
      onSeekTo={(s) => pb.seek(s)}
      onRetry={pb.retry}
      onExit={sair}
      videoFit={pb.hasVideoFit ? videoFit : undefined}
      onCycleVideoFit={pb.hasVideoFit ? ciclarFormato : undefined}
      liveEpg={epgAoVivo}
      nextEpisode={
        mostrarBannerProximo && proximoItem
          ? {
              title: proximoItem.title,
              secondsLeft: autoplayNext ? Math.max(0, Math.ceil(restanteSecs)) : null,
              onPlayNow: () => zap(1),
              onDismiss: () => setProximoDispensadoPara(item.id),
            }
          : undefined
      }
      onChannelStep={params.kind === 'live' ? zap : undefined}
      channelNumber={params.kind === 'live' ? fila[filaIndice]?.num : undefined}
      onOpenChannels={
        params.kind === 'live' && fila.length > 1
          ? () => {
              setCanaisAbertos(true);
              setFocus('player-channels-grid');
            }
          : undefined
      }
      onChannelNumber={
        params.kind === 'live'
          ? (numero) => {
              const i = fila.findIndex((c) => c.num === numero);
              if (i >= 0) irParaIndice(i);
            }
          : undefined
      }
      // Só no canal ao vivo: era o único jeito que faltava de favoritar um
      // canal (filme e série já têm o botão na tela de detalhes). Vale para o
      // canal que está no ar agora, então acompanha o zapping.
      isFavorite={params.kind === 'live' && isFav('live', item.id)}
      onToggleFavorite={
        params.kind === 'live' && list
          ? () => void alternarFavorito(rt, list.id, 'live', item.id)
          : undefined
      }
      // Válvula de escape para container/codec que o engine da casca não toca:
      // para a nossa sessão antes (o painel conta conexões) e sai da tela, para
      // o BACK do player externo não voltar num player parado.
      onExternalPlayer={
        adapter.openInExternalPlayer
          ? () => {
              void (async () => {
                const url = await resolveUrl();
                pb.stop();
                await adapter.openInExternalPlayer?.(url, item.title);
                pop();
              })();
            }
          : undefined
      }
      onOpenAudioSubtitles={
        pb.tracks.audio.length + pb.tracks.text.length > 0
          ? () => {
              setAudioOpen(true);
              setFocus('audiosub');
            }
          : undefined
      }
      overlay={
        canaisAbertos ? (
          <ChannelListOverlay
            items={fila}
            currentIndex={filaIndice}
            onPick={irParaIndice}
            listId={list?.id}
          />
        ) : audioOpen ? (
          <AudioSubtitlePanel
            audio={pb.tracks.audio}
            text={pb.tracks.text}
            activeAudioId={activeAudio ?? faixaPreferidaAudio?.id}
            activeTextId={
              activeText === undefined ? (faixaPreferidaTexto?.id ?? null) : activeText
            }
            onAudio={(id) => {
              pb.setAudioTrack(id);
              setActiveAudio(id);
              void atualizarPrefs(rt, { audioLang: idiomaDe(pb.tracks.audio, id) });
            }}
            onText={(id) => {
              pb.setTextTrack(id);
              setActiveText(id);
              void atualizarPrefs(rt, {
                subtitleLang: id === null ? 'off' : idiomaDe(pb.tracks.text, id),
              });
            }}
            onClose={() => {
              setAudioOpen(false);
              setFocus('player-playpause');
            }}
          />
        ) : undefined
      }
    />
  );
}
