import { useEffect, useState } from 'react';
import type { EpgEntry } from '@mfp/core';
import { hora } from '../state/nowNext.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

/**
 * Barra de progresso do programa no ar (D-22), no lugar em que o VOD mostra a
 * seekbar. Só aparece quando há EPG para o canal. O ponteiro anda no virar do
 * minuto — como o relógio do cabeçalho, sem gastar um tick por segundo.
 */
export function LiveProgress({
  now,
  next,
}: Readonly<{ now: EpgEntry; next?: EpgEntry }>) {
  const [agora, setAgora] = useState(() => Date.now());

  useEffect(() => {
    let timer: number;
    const agendar = () => {
      const d = Date.now();
      setAgora(d);
      timer = window.setTimeout(agendar, 60_000 - (d % 60_000) + 50);
    };
    agendar();
    return () => window.clearTimeout(timer);
  }, []);

  const dur = Math.max(1, now.stop - now.start);
  const frac = Math.min(1, Math.max(0, (agora - now.start) / dur));

  return (
    <div
      className={gapColClass}
      style={{ display: 'flex', flexDirection: 'column', ...gapVar('0.3rem') }}
    >
      <div style={{ minWidth: 0, lineHeight: 1.25 }}>
        <strong
          style={{
            fontSize: 'var(--fs-body)',
            display: 'block',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}
        >
          {now.title}
        </strong>
        {next && (
          <span
            style={{
              color: 'var(--text-secondary)',
              fontSize: 'var(--fs-meta)',
              display: 'block',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap',
            }}
          >
            {t('live.next')} {hora(next.start)} {next.title}
          </span>
        )}
      </div>
      <div
        className={gapRowClass}
        style={{
          display: 'flex',
          alignItems: 'center',
          fontSize: 'var(--fs-meta)',
          color: 'var(--text-secondary)',
          ...gapVar('0.6rem'),
        }}
      >
        <span>{hora(now.start)}</span>
        <div
          style={{
            flex: 1,
            height: '0.3rem',
            borderRadius: '0.15rem',
            background: 'var(--bg-raised)',
            overflow: 'hidden',
          }}
        >
          <div
            style={{
              width: `${frac * 100}%`,
              height: '100%',
              background: 'var(--accent)',
            }}
          />
        </div>
        <span>{hora(now.stop)}</span>
      </div>
    </div>
  );
}
