import { useCallback, useEffect, useRef, useState } from 'react';
import { useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import type { PlatformAdapter } from '@mfp/platform';
import { useLogicalKeys } from '../nav/keys.js';
import { formatTime } from './time.js';
import { gapRowClass, gapVar } from '../theme/gap.js';

export interface SeekBarProps {
  adapter: PlatformAdapter;
  positionSecs: number;
  durationSecs: number;
  /** Salta para uma posição absoluta. */
  onSeekTo: (secs: number) => void;
  /** Chamado a cada interação — o PlayerShell usa para reabrir/segurar o OSD. */
  onInteract?: () => void;
  focusKey?: string;
}

/** Passo base do scrub por D-pad; acelera se o usuário segura a seta. */
const BASE_STEP = 10;
const FAST_STEP = 30;
const TURBO_STEP = 60;
const REPEAT_WINDOW_MS = 400;
const COMMIT_DELAY_MS = 700;
/** Tolerância para considerar que o transporte chegou ao alvo do salto. */
const TARGET_REACHED_SECS = 2;
/** Se o transporte não chegar nesse tempo, para de segurar o alvo. */
const TARGET_TIMEOUT_MS = 8000;

/**
 * Barra de progresso operável (tela 13):
 * - **D-pad**: com foco, ←/→ fazem scrub (10s → 30s → 60s se segurar) sem sair
 *   da barra; o salto é confirmado ~0,7s depois de parar, ou na hora com OK.
 * - **Toque/clique**: salta direto para a posição tocada (útil em celular; a
 *   constitution §7 exige que nada *dependa* de toque, e não depende).
 *
 * Sem capítulos nem preview de thumbnail — cortados na v1 (decisions D-9).
 */
export function SeekBar({
  adapter,
  positionSecs,
  durationSecs,
  onSeekTo,
  onInteract,
  focusKey = 'player-seekbar',
}: SeekBarProps) {
  /** Salto ainda sendo composto pelo usuário (setas), não enviado. */
  const [pending, setPending] = useState<number | null>(null);
  /**
   * Salto já enviado, esperando o transporte chegar lá. Sem isto a barra volta
   * para a posição antiga no instante do commit — o ExoPlayer leva um tempo até
   * reportar a nova posição (medido no device) — e a seta seguinte recalcularia
   * a partir dessa base velha, fazendo o scrub "não acumular".
   */
  const [target, setTarget] = useState<number | null>(null);
  const commitTimer = useRef<number | null>(null);
  const targetSinceMs = useRef(0);
  const lastPress = useRef(0);
  const runLength = useRef(0);

  const seekable = durationSecs > 0;
  const shown = pending ?? target ?? positionSecs;
  const pct = seekable ? Math.max(0, Math.min(100, (shown / durationSecs) * 100)) : 0;

  const commit = useCallback(() => {
    if (commitTimer.current) window.clearTimeout(commitTimer.current);
    commitTimer.current = null;
    setPending((p) => {
      if (p != null) {
        targetSinceMs.current = Date.now();
        setTarget(p);
        onSeekTo(p);
      }
      return null;
    });
  }, [onSeekTo]);

  // solta o alvo quando o transporte chega perto dele (ou desiste de esperar)
  useEffect(() => {
    if (target == null) return;
    const chegou = Math.abs(positionSecs - target) <= TARGET_REACHED_SECS;
    const expirou = Date.now() - targetSinceMs.current > TARGET_TIMEOUT_MS;
    if (chegou || expirou) setTarget(null);
  }, [positionSecs, target]);

  // limpa o timer se o componente sair antes de confirmar
  useEffect(() => {
    return () => {
      if (commitTimer.current) window.clearTimeout(commitTimer.current);
    };
  }, []);

  const scrub = useCallback(
    (dir: -1 | 1) => {
      if (!seekable) return;
      onInteract?.();

      const now = Date.now();
      runLength.current =
        now - lastPress.current < REPEAT_WINDOW_MS ? runLength.current + 1 : 0;
      lastPress.current = now;
      const step =
        runLength.current > 10
          ? TURBO_STEP
          : runLength.current > 4
            ? FAST_STEP
            : BASE_STEP;

      setPending((p) => {
        const base = p ?? target ?? positionSecs;
        return Math.max(0, Math.min(durationSecs, base + dir * step));
      });

      if (commitTimer.current) window.clearTimeout(commitTimer.current);
      commitTimer.current = window.setTimeout(commit, COMMIT_DELAY_MS);
    },
    [seekable, positionSecs, target, durationSecs, commit, onInteract],
  );

  const { ref, focused } = useFocusable({ focusKey, focusable: seekable });

  // Com a barra focada, ←/→ fazem scrub e a tecla é **consumida** (devolvendo
  // `true`), senão o norigin moveria o foco para o botão vizinho. `onArrowPress`
  // do norigin não se mostrou confiável para isso no device.
  const active = focused && seekable;
  useLogicalKeys(adapter, {
    Left: () => {
      if (!active) return;
      scrub(-1);
      return true;
    },
    Right: () => {
      if (!active) return;
      scrub(1);
      return true;
    },
    Enter: () => {
      if (!active || pending == null) return;
      commit();
      return true;
    },
  });

  /** Há um salto em andamento (compondo ou a caminho): destaca o tempo/marcador. */
  const moving = pending != null || target != null;

  const seekFromPointer = (clientX: number) => {
    const el = ref.current as HTMLDivElement | null;
    if (!el || !seekable) return;
    const r = el.getBoundingClientRect();
    const ratio = Math.max(0, Math.min(1, (clientX - r.left) / r.width));
    const secs = ratio * durationSecs;
    onInteract?.();
    if (commitTimer.current) window.clearTimeout(commitTimer.current);
    commitTimer.current = null;
    setPending(null);
    targetSinceMs.current = Date.now();
    setTarget(secs);
    onSeekTo(secs);
  };

  return (
    <div
      className={gapRowClass}
      style={{ display: 'flex', alignItems: 'center', ...gapVar('0.8rem') }}
    >
      <span
        style={{
          fontVariantNumeric: 'tabular-nums',
          color: moving ? 'var(--accent)' : 'var(--text-primary)',
        }}
      >
        {formatTime(shown)}
      </span>

      <div
        ref={ref}
        role="slider"
        tabIndex={-1}
        aria-label="Progresso"
        aria-valuemin={0}
        aria-valuemax={Math.round(durationSecs)}
        aria-valuenow={Math.round(shown)}
        onClick={(e) => seekFromPointer(e.clientX)}
        style={{
          position: 'relative',
          flex: 1,
          // alvo de toque generoso, faixa fina desenhada dentro
          height: '1.6rem',
          display: 'flex',
          alignItems: 'center',
          cursor: seekable ? 'pointer' : 'default',
          outline: focused
            ? 'var(--focus-ring-width) solid var(--focus-ring)'
            : 'var(--focus-ring-width) solid transparent',
          outlineOffset: '0.2rem',
          borderRadius: 999,
        }}
      >
        <div
          style={{
            width: '100%',
            height: focused ? 8 : 6,
            borderRadius: 4,
            background: 'var(--bg-raised)',
            overflow: 'hidden',
            transition: 'height var(--dur-fast) var(--ease)',
          }}
        >
          <div
            style={{
              width: `${pct}%`,
              height: '100%',
              background: 'var(--accent)',
            }}
          />
        </div>
        {/* marcador da posição — cresce quando a barra está focada/em scrub */}
        {seekable && (
          <span
            aria-hidden
            style={{
              position: 'absolute',
              left: `${pct}%`,
              width: focused || moving ? '1rem' : '0.7rem',
              height: focused || moving ? '1rem' : '0.7rem',
              marginLeft: focused || moving ? '-0.5rem' : '-0.35rem',
              borderRadius: '50%',
              background: 'var(--accent)',
              boxShadow: focused ? 'var(--focus-glow)' : 'none',
              transition: 'width var(--dur-fast), height var(--dur-fast)',
            }}
          />
        )}
      </div>

      <span
        style={{ fontVariantNumeric: 'tabular-nums', color: 'var(--text-secondary)' }}
      >
        {formatTime(durationSecs)}
      </span>
    </div>
  );
}
