import { nullLogger, type Logger } from '../log/logger.js';
import { Emitter } from '../util/emitter.js';
import { systemClock, type Clock, type TimerHandle } from './clock.js';
import {
  DEFAULT_PLAYBACK_CONFIG,
  backoffDelaySecs,
  type PlaybackConfig,
} from './config.js';
import { errorPolicy } from './errorPolicy.js';
import type { BufferConfig, PlayerError, VideoPlayer } from './types.js';

export type PlaybackState =
  'IDLE' | 'OPENING' | 'BUFFERING' | 'PLAYING' | 'RECOVERING' | 'ENDED' | 'FAILED';

export type StreamKindPB = 'live' | 'vod';

export interface PlaybackSnapshot {
  state: PlaybackState;
  attempt: number;
  slowMode: boolean;
  error: PlayerError | null;
  positionSecs: number;
  durationSecs: number;
  isLive: boolean;
  waitingForNetwork: boolean;
  /**
   * Pausado pelo usuário. `state` continua PLAYING: a sessão está viva e o
   * watchdog não deve tratar a posição parada como travamento. A UI usa isso
   * para rotular o botão e manter os controles visíveis enquanto pausado.
   */
  paused: boolean;
}

export interface PlaybackEvents {
  state: { from: PlaybackState; to: PlaybackState; reason: string };
  snapshot: PlaybackSnapshot;
  /** progresso confirmado como reproduzido (VOD) — o app grava no cache (§9). */
  progress: { positionSecs: number; durationSecs: number; completed: boolean };
  /** a UI deve reconstruir `resolveUrl` com o outro formato e chamar `retry()` (§5.8). */
  formatSwapRequested: Record<string, never>;
}

export interface OpenOptions {
  kind: StreamKindPB;
  buffer: BufferConfig;
  startAtSecs?: number;
}

export interface PlaybackDeps {
  player: VideoPlayer;
  /** rebuild da URL de stream a cada tentativa (redirect/token/nó) — RF-60. */
  resolveUrl: (ctx: { reauth: boolean; attempt: number }) => Promise<string>;
  isOnline: () => boolean;
  onOnline: (cb: () => void) => () => void;
  config?: PlaybackConfig;
  logger?: Logger;
  clock?: Clock;
}

/**
 * Cérebro da reprodução (playback-design.md §1/§2). Neutro de plataforma: consome
 * um `VideoPlayer` "burro" e concentra máquina de estado, watchdog de travamento,
 * backoff com full jitter, teto de tentativas, modo lento do live e preservação de
 * posição. A UI observa só este controller.
 */
export class PlaybackController {
  readonly events = new Emitter<PlaybackEvents>();

  private readonly cfg: PlaybackConfig;
  private readonly log: Logger;
  private readonly clock: Clock;
  private readonly offs: Array<() => void> = [];

  private state: PlaybackState = 'IDLE';
  private kind: StreamKindPB = 'live';
  private buffer: BufferConfig | null = null;
  private attempt = 0;
  private slowMode = false;
  private slowModeStartedAt = 0;
  private lastError: PlayerError | null = null;
  private waitingForNetwork = false;

  private confirmedPosition = 0; // última posição vista em PLAYING (resume de VOD)
  private paused = false;
  private durationSecs = 0;
  private nudgedThisSession = false;
  private stuckSinceMs: number | null = null;
  private bufferingSinceMs: number | null = null;
  private lastWatchPos = 0;
  private lastProgressSaveMs = 0;

  private watchdog: TimerHandle | null = null;
  private openTimer: TimerHandle | null = null;
  private backoffTimer: TimerHandle | null = null;
  private offOnline: (() => void) | null = null;

  constructor(private readonly deps: PlaybackDeps) {
    this.cfg = deps.config ?? DEFAULT_PLAYBACK_CONFIG;
    this.log = (deps.logger ?? nullLogger).child({ mod: 'playback' });
    this.clock = deps.clock ?? systemClock;
    this.wirePlayer();
  }

  get snapshot(): PlaybackSnapshot {
    return {
      state: this.state,
      attempt: this.attempt,
      slowMode: this.slowMode,
      error: this.lastError,
      positionSecs: this.confirmedPosition,
      durationSecs: this.durationSecs,
      isLive: this.kind === 'live',
      waitingForNetwork: this.waitingForNetwork,
      paused: this.paused,
    };
  }

  /** Abre um novo stream. Garante `stop()` do anterior antes de `load()` (RF-12/§8). */
  async open(opts: OpenOptions): Promise<void> {
    this.teardownTimers();
    this.deps.player.stop();
    this.kind = opts.kind;
    this.buffer = opts.buffer;
    this.attempt = 0;
    this.slowMode = false;
    this.lastError = null;
    this.nudgedThisSession = false;
    this.paused = false;
    this.confirmedPosition = opts.startAtSecs ?? 0;
    this.transition('OPENING', 'open');
    await this.loadCurrent({ reauth: false });
  }

  play(): void {
    this.paused = false;
    this.deps.player.play();
    this.emitSnapshot();
  }

  pause(): void {
    this.paused = true;
    this.deps.player.pause();
    this.emitProgress(false);
    this.emitSnapshot();
  }

  seek(secs: number): void {
    this.deps.player.seek(secs);
  }

  /** Sai do player: para o transporte, salva progresso, remove watchdog (§8). */
  stop(): void {
    this.teardownTimers();
    this.deps.player.stop();
    this.emitProgress(false);
    this.transition('IDLE', 'stop');
  }

  /** Botão "Tentar novamente" da ErrorScreen (§5.8): zera tudo e reabre. */
  retry(): void {
    if (this.state !== 'FAILED') return;
    this.attempt = 0;
    this.slowMode = false;
    this.lastError = null;
    this.nudgedThisSession = false;
    this.transition('OPENING', 'user-retry');
    void this.loadCurrent({ reauth: false });
  }

  destroy(): void {
    this.teardownTimers();
    this.offs.forEach((off) => off());
    this.offOnline?.();
    this.events.clear();
  }

  // ---- interno -----------------------------------------------------------

  private wirePlayer(): void {
    const p = this.deps.player;
    this.offs.push(
      p.on('playing', () => this.onPlaying()),
      p.on('buffering', () => this.onBuffering()),
      p.on('ended', () => this.onEnded()),
      p.on('paused', () => this.onPaused()),
      p.on('error', (e) => this.onPlayerError(e)),
      p.on('positionchanged', (secs) => this.onPosition(secs)),
    );
  }

  private async loadCurrent(ctx: { reauth: boolean }): Promise<void> {
    if (!this.buffer) return;
    this.clock.clearTimeout(this.openTimer);
    this.openTimer = this.clock.setTimeout(
      () => this.recover({ code: 'NET_TIMEOUT' }, 'open-timeout'),
      this.cfg.openTimeoutSecs * 1000,
    );
    try {
      const url = await this.deps.resolveUrl({
        reauth: ctx.reauth,
        attempt: this.attempt,
      });
      this.deps.player.stop();
      await this.deps.player.load(url, {
        kind: this.kind,
        startAtSecs: this.kind === 'vod' ? this.confirmedPosition : undefined,
        buffer: this.buffer,
      });
      this.deps.player.play();
      this.transition('BUFFERING', 'load');
      this.startWatchdog();
    } catch (err) {
      this.clock.clearTimeout(this.openTimer);
      this.recover({ code: 'NET_DROPPED', detail: String(err) }, 'load-threw');
    }
  }

  private onPlaying(): void {
    this.clock.clearTimeout(this.openTimer);
    this.paused = false;
    this.bufferingSinceMs = null;
    this.stuckSinceMs = null;
    this.attempt = 0;
    this.slowMode = false;
    this.waitingForNetwork = false;
    this.durationSecs = this.deps.player.getDurationSecs();
    this.transition('PLAYING', 'player-playing');
  }

  /** Pausa vinda do transporte (inclusive foco/áudio perdido, não só do usuário). */
  private onPaused(): void {
    this.paused = true;
    this.emitProgress(false);
    this.emitSnapshot();
  }

  private onBuffering(): void {
    if (this.state === 'PLAYING' || this.state === 'OPENING') {
      this.bufferingSinceMs = this.clock.now();
      this.transition('BUFFERING', 'player-buffering');
    }
  }

  private onEnded(): void {
    if (this.kind === 'vod') {
      this.emitProgress(true);
      this.teardownTimers();
      this.transition('ENDED', 'player-ended');
    } else {
      // live não "termina" — trate como queda
      this.recover({ code: 'NET_DROPPED' }, 'live-ended');
    }
  }

  private onPlayerError(e: PlayerError): void {
    const policy = errorPolicy(e.code);
    if (policy.severity === 'fatal') {
      this.fail(e, `fatal:${e.code}`);
      if (policy.suggestFormatSwap) this.events.emit('formatSwapRequested', {});
      return;
    }
    this.recover(e, `player-error:${e.code}`);
  }

  private onPosition(secs: number): void {
    // A duração é um fato do transporte, não depende do estado: pode só ficar
    // conhecida depois do `playing` (ponte assíncrona do plugin nativo) ou mudar
    // ao trocar de item. Reler sempre mantém a seekbar correta sem alterar o
    // contrato do VideoPlayer.
    this.durationSecs = this.deps.player.getDurationSecs();

    // A posição confirmada só avança tocando de fato — numa reconexão é dela que
    // sai o `startAtSecs` (playback-design.md §9).
    if (this.state === 'PLAYING') {
      this.confirmedPosition = secs;
      const dueMs = this.cfg.progressSaveEverySecs * 1000;
      if (this.clock.now() - this.lastProgressSaveMs >= dueMs) this.emitProgress(false);
    }

    // O tick do transporte é ~1/s: publicar sempre é barato e é o que mantém o
    // relógio e a seekbar vivos. (`emitProgress` NÃO publica snapshot — ele só
    // emite `progress`, e nem isso para live.)
    this.emitSnapshot();
  }

  // ---- watchdog (§4) ----------------------------------------------------

  private startWatchdog(): void {
    this.clock.clearInterval(this.watchdog);
    this.lastWatchPos = this.deps.player.getPositionSecs();
    this.stuckSinceMs = null;
    // Cada sessão ganha o orçamento de buffering inteiro. Sem este reset, uma
    // abertura que nunca chega a tocar deixa `bufferingSinceMs` do primeiro
    // load valendo para sempre — a partir daí toda retentativa estoura o limite
    // no primeiro tick e o backoff vira uma espiral de reconexões de ~1s
    // (medido no device: load → stop em 1s, com os decoders já alocados).
    this.bufferingSinceMs = this.clock.now();
    this.watchdog = this.clock.setInterval(() => this.tickWatchdog(), 1000);
  }

  private tickWatchdog(): void {
    const now = this.clock.now();
    const s = this.cfg.stall;

    if (this.state === 'BUFFERING') {
      if (this.bufferingSinceMs == null) this.bufferingSinceMs = now;
      const limit = this.kind === 'live' ? s.liveBufferSecs : s.vodBufferSecs;
      if (now - this.bufferingSinceMs >= limit * 1000) {
        this.recover({ code: 'STALL' }, 'buffering-timeout');
      }
      return;
    }

    // Pausado é posição parada de propósito: nem nudge nem reinício de sessão.
    if (this.state !== 'PLAYING' || this.paused) {
      this.stuckSinceMs = null;
      return;
    }

    const pos = this.deps.player.getPositionSecs();
    const moved = Math.abs(pos - this.lastWatchPos) >= 0.25;
    this.lastWatchPos = pos;

    if (moved) {
      this.stuckSinceMs = null;
      return;
    }
    if (this.stuckSinceMs == null) this.stuckSinceMs = now;
    const stuckSecs = (now - this.stuckSinceMs) / 1000;

    if (
      !this.nudgedThisSession &&
      stuckSecs >= s.nudgeAfterSecs &&
      stuckSecs < (this.kind === 'live' ? s.livePlaySecs : s.vodPlaySecs)
    ) {
      this.nudgedThisSession = true;
      const target =
        this.kind === 'live'
          ? this.deps.player.getDurationSecs() // borda ao vivo
          : pos + 0.1;
      this.log.info('nudge de travamento', { kind: this.kind, target });
      this.deps.player.seek(target);
      return;
    }

    const restartAt = this.kind === 'live' ? s.livePlaySecs : s.vodPlaySecs;
    if (stuckSecs >= restartAt) this.recover({ code: 'STALL' }, 'stall-restart');
  }

  // ---- reconexão (§5) -------------------------------------------------

  private recover(error: PlayerError, reason: string): void {
    if (this.state === 'FAILED' || this.state === 'ENDED') return;
    this.lastError = error;
    this.clock.clearTimeout(this.openTimer);
    this.clock.clearInterval(this.watchdog);
    this.watchdog = null;

    const policy = errorPolicy(error.code);
    const globalCap =
      this.kind === 'live' ? this.cfg.maxAttempts.live : this.cfg.maxAttempts.vod;

    // teto próprio da classe (ex.: 401/403 = 1×) → fatal, nunca entra em modo lento
    if (policy.maxOwnAttempts != null && this.attempt >= policy.maxOwnAttempts) {
      this.fail(error, `own-attempts-exhausted:${error.code}`);
      return;
    }

    if (this.attempt >= globalCap) {
      if (this.kind === 'live' && !this.slowMode) {
        this.slowMode = true;
        this.slowModeStartedAt = this.clock.now();
        this.log.info('live entrou em modo lento', { attempt: this.attempt });
      } else if (
        this.kind === 'live' &&
        this.clock.now() - this.slowModeStartedAt >= this.cfg.slowRetry.forSecs * 1000
      ) {
        this.fail(error, 'slow-mode-exhausted');
        return;
      } else if (this.kind === 'vod') {
        this.fail(error, 'attempts-exhausted');
        return;
      }
    }

    this.transition('RECOVERING', reason);

    if (!this.deps.isOnline()) {
      this.waitingForNetwork = true;
      this.emitSnapshot();
      this.offOnline?.();
      this.offOnline = this.deps.onOnline(() => {
        this.waitingForNetwork = false;
        this.offOnline?.();
        this.offOnline = null;
        // rede voltou: retoma na hora, sem esperar backoff (§5.4)
        this.attempt += 1;
        this.nudgedThisSession = false;
        void this.loadCurrent({ reauth: policy.reauth });
      });
      return;
    }

    const delaySecs = this.slowMode
      ? this.cfg.slowRetry.intervalSecs
      : backoffDelaySecs(this.cfg, this.attempt + 1, () => this.clock.random());
    this.scheduleAttempt(policy.reauth, delaySecs);
  }

  private scheduleAttempt(reauth: boolean, delaySecs: number): void {
    this.clock.clearTimeout(this.backoffTimer);
    this.backoffTimer = this.clock.setTimeout(() => {
      this.attempt += 1;
      this.nudgedThisSession = false;
      this.log.info('tentando reconectar', {
        attempt: this.attempt,
        slowMode: this.slowMode,
        reauth,
      });
      void this.loadCurrent({ reauth });
    }, delaySecs * 1000);
  }

  private fail(error: PlayerError, reason: string): void {
    this.teardownTimers();
    this.deps.player.stop();
    this.lastError = error;
    this.transition('FAILED', reason);
  }

  private emitProgress(completed: boolean): void {
    this.lastProgressSaveMs = this.clock.now();
    if (this.kind !== 'vod') return;
    this.events.emit('progress', {
      positionSecs: this.confirmedPosition,
      durationSecs: this.durationSecs,
      completed:
        completed ||
        (this.durationSecs > 0 &&
          this.confirmedPosition / this.durationSecs >= this.cfg.resumeWindow.maxPct),
    });
  }

  private teardownTimers(): void {
    this.clock.clearInterval(this.watchdog);
    this.clock.clearTimeout(this.openTimer);
    this.clock.clearTimeout(this.backoffTimer);
    this.watchdog = this.openTimer = this.backoffTimer = null;
    this.offOnline?.();
    this.offOnline = null;
    this.waitingForNetwork = false;
  }

  private transition(to: PlaybackState, reason: string): void {
    const from = this.state;
    if (from === to) {
      this.emitSnapshot();
      return;
    }
    this.state = to;
    this.log.info('transição de estado', {
      from,
      to,
      reason,
      attempt: this.attempt,
      pos: this.confirmedPosition,
    });
    this.events.emit('state', { from, to, reason });
    this.emitSnapshot();
  }

  private emitSnapshot(): void {
    this.events.emit('snapshot', this.snapshot);
  }
}
