import type { PlayerErrorCode } from './types.js';

// playback-design.md §3. "recoverable" conta tentativa; "fatal" nunca reentra.

export type ErrorSeverity = 'recoverable' | 'fatal';

export interface ErrorPolicy {
  severity: ErrorSeverity;
  /** rebuild da URL + re-auth da lista antes de tentar de novo (401/403). */
  reauth: boolean;
  /** teto próprio de tentativas para esta classe, além do teto global. */
  maxOwnAttempts?: number;
  /** dica para a UI: sugerir troca de formato ts↔m3u8. */
  suggestFormatSwap?: boolean;
  /** dica para a UI: oferecer player externo (Android). */
  suggestExternalPlayer?: boolean;
}

const POLICY: Record<PlayerErrorCode, ErrorPolicy> = {
  NET_TIMEOUT: { severity: 'recoverable', reauth: false },
  NET_DROPPED: { severity: 'recoverable', reauth: false },
  HTTP_5XX: { severity: 'recoverable', reauth: false },
  HTTP_401: { severity: 'recoverable', reauth: true, maxOwnAttempts: 1 },
  HTTP_403: { severity: 'recoverable', reauth: true, maxOwnAttempts: 1 },
  HTTP_404: { severity: 'fatal', reauth: false },
  SRC_PARSE: {
    severity: 'recoverable',
    reauth: false,
    maxOwnAttempts: 2,
    suggestFormatSwap: true,
  },
  DECODE: {
    severity: 'fatal',
    reauth: false,
    suggestFormatSwap: true,
    suggestExternalPlayer: true,
  },
  DRM: { severity: 'fatal', reauth: false },
  STALL: { severity: 'recoverable', reauth: false },
  UNKNOWN: { severity: 'recoverable', reauth: false, maxOwnAttempts: 1 },
};

export function errorPolicy(code: PlayerErrorCode): ErrorPolicy {
  return POLICY[code];
}
