import { useEffect, useRef, useState } from 'react';
import {
  FocusContext,
  useFocusable,
  setFocus,
} from '@noriginmedia/norigin-spatial-navigation';
import type { EpgEntry, PlaybackSnapshot, VideoFit } from '@mfp/core';
import { LiveProgress } from './LiveProgress.js';
import { FocusButton } from '../components/FocusButton.js';
import { ErrorScreen } from '../components/states.js';
import { PlayIcon, PauseIcon } from '../components/icons.js';
import { BalanceLoader } from '../components/BalanceLoader.js';
import { useLogicalKeys } from '../nav/keys.js';
import { useBackHandler } from '../nav/backStack.js';
import type { PlatformAdapter } from '@mfp/platform';
import { SeekBar } from './SeekBar.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar, gapWrapClass, gapWrapInnerClass } from '../theme/gap.js';

export interface PlayerShellProps {
  adapter: PlatformAdapter;
  title: string;
  subtitle?: string;
  mountRef: React.RefObject<HTMLDivElement>;
  snapshot: PlaybackSnapshot;
  onPlayPause: () => void;
  onSeekRelative: (deltaSecs: number) => void;
  /** salto para posição absoluta (seekbar). */
  onSeekTo: (secs: number) => void;
  onRetry: () => void;
  onExit: () => void;
  /** zapping ao vivo (ChannelUp/Down). */
  onChannelStep?: (delta: number) => void;
  onOpenAudioSubtitles?: () => void;
  /**
   * Favoritar o que está no ar. Ausente = sem botão (só o canal ao vivo usa;
   * filme e episódio já têm o botão na tela de detalhes).
   */
  onToggleFavorite?: () => void;
  isFavorite?: boolean;
  /** Entregar o stream a um player do sistema. Ausente = plataforma sem suporte. */
  onExternalPlayer?: () => void;
  /** Abre a lista de canais sobreposta (só ao vivo). */
  onOpenChannels?: () => void;
  /** Número digitado no controle — salto direto de canal (só ao vivo). */
  onChannelNumber?: (num: number) => void;
  /** Número do canal no ar, para a barra de info. */
  channelNumber?: number;
  /** slot para overlays (AudioSubtitlePanel, lista de canais…). */
  overlay?: React.ReactNode;
  /** Formato de exibição atual (D-21). Ausente = plataforma sem suporte. */
  videoFit?: VideoFit;
  /** Cicla o formato de exibição (Original → Preencher → 16:9 → 4:3). */
  onCycleVideoFit?: () => void;
  /** Programa no ar / a seguir do canal ao vivo (D-22). Ausente = sem guia. */
  liveEpg?: { now?: EpgEntry; next?: EpgEntry } | null;
  /**
   * Banner de "próximo episódio" (últimos 15s do VOD atual, com fila). Ausente
   * = sem próximo item, ou já dispensado para este episódio.
   */
  nextEpisode?: {
    title: string;
    /** Segundos restantes até o auto-avanço; `null` = sem contagem (avanço automático desligado). */
    secondsLeft: number | null;
    onPlayNow: () => void;
    onDismiss: () => void;
  } | null;
}

/** Tempo sem tocar no controle até o OSD sumir (reinicia a cada tecla). */
const OSD_ESCONDE_MS = 6000;

const ROTULO_FIT: Record<VideoFit, Parameters<typeof t>[0]> = {
  original: 'player.fitOriginal',
  fill: 'player.fitFill',
  '16:9': 'player.fit169',
  '4:3': 'player.fit43',
};

/** Casca do player (tela 03/13): vídeo em tela cheia + overlay de controles D-pad. */
export function PlayerShell({
  adapter,
  title,
  subtitle,
  mountRef,
  snapshot,
  onPlayPause,
  onSeekRelative,
  onSeekTo,
  onRetry,
  onExit,
  onChannelStep,
  onOpenAudioSubtitles,
  onToggleFavorite,
  isFavorite = false,
  onExternalPlayer,
  onOpenChannels,
  onChannelNumber,
  channelNumber,
  overlay,
  videoFit,
  onCycleVideoFit,
  liveEpg,
  nextEpisode,
}: PlayerShellProps) {
  const [chromeVisible, setChromeVisible] = useState(true);
  // Nonce que muda a cada interação com o controle — reinicia a contagem do
  // auto-esconder. Sem isto, o timer começava a contar quando o OSD abria e não
  // resetava ao navegar (o `wake` só setava `true`, que já era `true`), então
  // o menu sumia no meio da navegação. Medido numa TV real.
  const [interacao, setInteracao] = useState(0);
  const { ref, focusKey } = useFocusable({ focusKey: 'player', trackChildren: true });

  useEffect(() => {
    setFocus('player-playpause');
    // libera o "hole-punch": deixa body/#root transparentes enquanto o player
    // está aberto para o SurfaceView nativo (Android) aparecer atrás do WebView.
    document.documentElement.setAttribute('data-player', '');
    return () => document.documentElement.removeAttribute('data-player');
  }, []);

  // auto-esconde os controles após um tempo **sem interação** — mas nunca
  // enquanto não está tocando de fato (abrindo / carregando / reconectando /
  // erro), com um overlay aberto, ou pausado: nesses momentos o usuário precisa
  // ver o status, e sumir com a barra durante a pausa deixa a tela sem explicação.
  const keepChrome = snapshot.state !== 'PLAYING' || snapshot.paused || !!overlay;
  useEffect(() => {
    if (!chromeVisible || keepChrome) return;
    // `interacao` nas dependências: cada tecla do controle reinicia esta contagem
    const id = window.setTimeout(() => setChromeVisible(false), OSD_ESCONDE_MS);
    return () => window.clearTimeout(id);
  }, [chromeVisible, keepChrome, interacao]);

  // ao reaparecer, devolve o foco pro play/pause — senão a barra volta "morta"
  // (os botões são desmontados quando escondida, o norigin fica sem alvo).
  // Não entra em jogo com o banner de próximo episódio: como a barra normal
  // cede lugar a ele, 'player-playpause' nem existe no DOM nesse momento —
  // sem este `!nextEpisode`, qualquer tecla que chamasse `wake()` (inclusive
  // tentando navegar até os botões do banner) roubava o foco de volta para
  // uma chave morta, e o OK parava de acionar qualquer coisa.
  useEffect(() => {
    if (chromeVisible && !overlay && !nextEpisode) setFocus('player-playpause');
  }, [chromeVisible, overlay, nextEpisode]);

  const wake = () => {
    setChromeVisible(true);
    setInteracao((n) => n + 1);
  };

  // OSD de número: digitar no controle salta de canal, como numa TV. O dígito
  // não passa pelo `keyMap` (é tecla comum), então é lido do `keydown` direto.
  // Fecha sozinho depois de 2s parado — é o tempo de digitar o 2º/3º dígito.
  const [digitos, setDigitos] = useState('');
  // O callback vem inline do `Player` e muda de identidade a cada render — e o
  // player re-renderiza a cada segundo com a posição. Num efeito com ele nas
  // dependências, o timer abaixo era cancelado e recriado a cada segundo e
  // NUNCA chegava aos 2s: o salto por número não acontecia. Por isso, ref.
  const numeroRef = useRef(onChannelNumber);
  useEffect(() => {
    numeroRef.current = onChannelNumber;
  });

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (!numeroRef.current || !/^\d$/.test(e.key)) return;
      e.preventDefault();
      setChromeVisible(true);
      setDigitos((d) => (d.length >= 4 ? e.key : d + e.key));
    };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, []);

  useEffect(() => {
    if (!digitos) return;
    const id = window.setTimeout(() => {
      numeroRef.current?.(Number(digitos));
      setDigitos('');
    }, 2000);
    return () => window.clearTimeout(id);
  }, [digitos]);

  // BACK pela pilha de overlays (backStack), não por um 2º listener de `keydown`:
  // o handler do `App` roda primeiro (montou antes) e, sem isso, desempilhava a
  // rota do player **antes** de o `onExit` daqui ter chance de só fechar o
  // overlay de canais / o painel de áudio. Medido na AVD de TV: um BACK fechava
  // o overlay e saía do player de uma vez. Agora o `App` chama `handleBack()`
  // primeiro e nos cede a vez.
  useBackHandler(onExit);

  useLogicalKeys(adapter, {
    // qualquer tecla do D-pad (inclusive OK) traz a barra de volta
    Enter: wake,
    Up: wake,
    Down: wake,
    Left: wake,
    Right: wake,
    Play: wake,
    Pause: wake,
    PlayPause: () => {
      wake();
      onPlayPause();
    },
    Rewind: () => {
      wake();
      onSeekRelative(-10);
    },
    FastForward: () => {
      wake();
      onSeekRelative(10);
    },
    ChannelUp: () => onChannelStep?.(1),
    ChannelDown: () => onChannelStep?.(-1),
    // mesma tecla da lista de canais (ver `LiveChannels`)
    Yellow: () => {
      wake();
      onToggleFavorite?.();
    },
    // atalho para ciclar o formato de exibição (D-21)
    Blue: () => {
      wake();
      onCycleVideoFit?.();
    },
  });

  const { state, attempt, slowMode, isLive, positionSecs, durationSecs, error } =
    snapshot;
  const overlayMsg =
    state === 'OPENING'
      ? t('player.opening')
      : state === 'BUFFERING'
        ? t('player.buffering')
        : state === 'RECOVERING'
          ? snapshot.waitingForNetwork
            ? t('player.waitingNetwork')
            : slowMode
              ? t('player.reconnectingSlow')
              : t('player.reconnecting', { n: attempt })
          : null;

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        style={{ position: 'fixed', top: 0, right: 0, bottom: 0, left: 0, overflow: 'hidden' }}
      >
        {/* Área do vídeo — SEM fundo: no Android o SurfaceView nativo aparece
            atrás do WebView (hole-punch); no apps/dev o <video> renderiza aqui
            e ele mesmo tem fundo preto.
            O toque nela alterna o OSD (a barra de controles fica por cima e
            recebe os toques dela mesma). Em TV nada depende disso — o D-pad
            faz o mesmo (constitution §7). */}
        <div
          ref={mountRef}
          onClick={() => setChromeVisible((v) => !v)}
          style={{ position: 'absolute', top: 0, right: 0, bottom: 0, left: 0 }}
        />

        {state === 'FAILED' && (
          <div
            style={{
              position: 'absolute',
              top: 0,
              right: 0,
              bottom: 0,
              left: 0,
              background: 'var(--bg-scrim)',
            }}
          >
            <ErrorScreen
              title={t('player.failed')}
              body={title}
              code={error?.code}
              onRetry={onRetry}
            />
          </div>
        )}

        {overlayMsg && (
          <div
            role="status"
            className={gapRowClass}
            style={{
              position: 'absolute',
              top: '2rem',
              left: '2rem',
              padding: '0.5rem 1rem',
              borderRadius: 'var(--radius-sm)',
              background: 'var(--bg-scrim)',
              color: 'var(--text-primary)',
              display: 'flex',
              alignItems: 'center',
              ...gapVar('0.7rem'),
            }}
          >
            {/* mesmo balanço das telas de carregamento, em escala de linha */}
            <BalanceLoader size="1.1em" />
            {/* `.mfp-gap-row` (`gap` via margin, ver `theme/gap.ts`) só sabe
                inserir espaço entre ELEMENTOS (`> * + *`) — texto solto não é
                selecionável por CSS. Sem o `<span>`, o texto ficava colado no
                balanço, sem respiro (achado numa TV LG real, 2026-09-14). */}
            <span>{overlayMsg}</span>
          </div>
        )}

        {/* Com um painel lateral aberto (canais, áudio/legendas) a barra sai:
            ela ocupa a largura toda embaixo e passava por cima da lista. O
            `keepChrome` acima segura o estado, então ela volta ao fechar.
            Com o banner de próximo episódio também: os dois disputavam a
            mesma área e o D-pad (que chama `wake()` em qualquer seta, mesmo
            tentando chegar nos botões do banner) reabria esta barra por
            cima, roubando o foco — por isso ela cede o lugar ao banner. */}
        {chromeVisible && state !== 'FAILED' && !overlay && !nextEpisode && (
          <div
            className={gapColClass}
            style={{
              position: 'absolute',
              left: 0,
              right: 0,
              bottom: 0,
              padding: '2rem var(--safe-x)',
              background: 'linear-gradient(transparent, rgba(0,0,0,0.85))',
              display: 'flex',
              flexDirection: 'column',
              ...gapVar('0.8rem'),
            }}
          >
            <div
              className={gapRowClass}
              style={{ display: 'flex', alignItems: 'center', ...gapVar('0.8rem') }}
            >
              {isLive && (
                <span
                  style={{
                    background: 'var(--live)',
                    color: '#fff',
                    fontWeight: 700,
                    fontSize: '0.8em',
                    padding: '0.1em 0.5em',
                    borderRadius: 4,
                  }}
                >
                  ● {t('player.live')}
                </span>
              )}
              {channelNumber !== undefined && (
                <span style={{ color: 'var(--text-secondary)', fontWeight: 700 }}>
                  {channelNumber}
                </span>
              )}
              <strong>{title}</strong>
              {subtitle && (
                <span style={{ color: 'var(--text-secondary)' }}>{subtitle}</span>
              )}
            </div>

            {!isLive && (
              <SeekBar
                adapter={adapter}
                positionSecs={positionSecs}
                durationSecs={durationSecs}
                onSeekTo={onSeekTo}
                onInteract={wake}
              />
            )}

            {isLive && liveEpg?.now && (
              <LiveProgress now={liveEpg.now} next={liveEpg.next} />
            )}

            <div className={gapWrapClass}>
              <div
                className={gapWrapInnerClass}
                style={{ display: 'flex', flexWrap: 'wrap', ...gapVar('0.8rem') }}
              >
              {!isLive && (
                <FocusButton focusKey="player-back10" onPress={() => onSeekRelative(-10)}>
                  ⏪ {t('player.back10')}
                </FocusButton>
              )}
              <FocusButton
                primary
                focusKey="player-playpause"
                onPress={onPlayPause}
                title={
                  state === 'PLAYING' && !snapshot.paused
                    ? t('player.pause')
                    : t('player.play')
                }
              >
                {state === 'PLAYING' && !snapshot.paused ? <PauseIcon /> : <PlayIcon />}
              </FocusButton>
              {!isLive && (
                <FocusButton focusKey="player-fwd10" onPress={() => onSeekRelative(10)}>
                  {t('player.forward10')} ⏩
                </FocusButton>
              )}
              {onOpenAudioSubtitles && (
                <FocusButton focusKey="player-audiosub" onPress={onOpenAudioSubtitles}>
                  {t('player.audioSubtitles')}
                </FocusButton>
              )}
              {onToggleFavorite && (
                <FocusButton focusKey="player-fav" onPress={onToggleFavorite}>
                  {isFavorite ? t('live.inFavorites') : t('live.favorite')}
                </FocusButton>
              )}
              {onCycleVideoFit && videoFit && (
                <FocusButton focusKey="player-fit" onPress={onCycleVideoFit}>
                  {t('player.videoFit')}: {t(ROTULO_FIT[videoFit])}
                </FocusButton>
              )}
              {onOpenChannels && (
                <FocusButton focusKey="player-channels-open" onPress={onOpenChannels}>
                  {t('player.channels')}
                </FocusButton>
              )}
              {onExternalPlayer && (
                <FocusButton focusKey="player-external" onPress={onExternalPlayer}>
                  {t('player.externalPlayer')}
                </FocusButton>
              )}
              </div>
            </div>
          </div>
        )}

        {/* Banner de próximo episódio (últimos 15s), largura toda — estilo
            XCIPTV/Netflix. Substitui a barra normal (acima) em vez de
            disputar espaço/foco com ela; fica visível mesmo depois do OSD
            sumir por inatividade. Não aparece com outro overlay já aberto. */}
        {nextEpisode && !overlay && (
          <div
            role="status"
            className={gapWrapClass}
            style={{
              position: 'absolute',
              left: 0,
              right: 0,
              bottom: 0,
              padding: '2rem var(--safe-x)',
              background: 'linear-gradient(transparent, rgba(0,0,0,0.9))',
            }}
          >
            <div
              className={gapWrapInnerClass}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                flexWrap: 'wrap',
                ...gapVar('1.5rem'),
              }}
            >
            <div style={{ minWidth: 0 }}>
              <div style={{ color: 'var(--text-secondary)', fontSize: '0.85em' }}>
                {t('player.nextEpisodeUp')}
              </div>
              <strong
                style={{
                  display: 'block',
                  fontSize: '1.15em',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}
              >
                {nextEpisode.title}
              </strong>
            </div>
            <div
              className={gapRowClass}
              style={{ display: 'flex', flexShrink: 0, ...gapVar('0.8rem') }}
            >
              <FocusButton focusKey="player-next-cancel" onPress={nextEpisode.onDismiss}>
                {t('player.cancelNext')}
              </FocusButton>
              <FocusButton
                primary
                autoFocus
                focusKey="player-next-episode"
                onPress={nextEpisode.onPlayNow}
              >
                {nextEpisode.secondsLeft != null
                  ? t('player.playNextIn', { n: nextEpisode.secondsLeft })
                  : t('player.playNextNow')}
              </FocusButton>
            </div>
            </div>
          </div>
        )}

        {digitos && (
          <div
            style={{
              position: 'absolute',
              top: '2rem',
              right: 'var(--safe-x)',
              padding: '0.4em 0.8em',
              borderRadius: 'var(--radius-sm)',
              background: 'var(--bg-scrim)',
              fontFamily: 'var(--font-display)',
              fontSize: 'var(--fs-title)',
              letterSpacing: '0.1em',
            }}
          >
            {digitos}
          </div>
        )}

        {overlay}
      </div>
    </FocusContext.Provider>
  );
}
