import { useEffect, useState } from 'react';
import { FocusContext, useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import type { EpgEntry } from '@mfp/core';
import { VirtualGrid } from '../components/VirtualGrid.js';
import { focusRing } from '../nav/focusRing.js';
import { useRemPx } from '../theme/useRemPx.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import type { QueueItem } from '../state/nowPlaying.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

/**
 * Lista de canais **dentro** do player (tela 03): troca de canal sem voltar para
 * a grade e sem derrubar o que está tocando. Os itens são a própria fila de
 * reprodução — a mesma que o zapping por ChannelUp/Down percorre —, então a
 * ordem aqui é a ordem de lá.
 *
 * Ocupa só um terço da largura: o ponto é continuar vendo o vídeo enquanto
 * escolhe. Fecha pelo BACK, como os demais overlays do player.
 */
export function ChannelListOverlay({
  items,
  currentIndex,
  onPick,
  listId,
}: Readonly<{
  items: QueueItem[];
  currentIndex: number;
  onPick: (index: number) => void;
  /** para buscar o programa no ar de cada canal (D-22). Ausente = sem guia. */
  listId?: string;
}>) {
  const rem = useRemPx();
  const rt = useRuntime();
  const { ref, focusKey } = useFocusable({
    focusKey: 'player-channels',
    trackChildren: true,
  });

  // programa no ar de cada canal, numa consulta só; atualiza no virar do minuto
  const [agora, setAgora] = useState<Map<string, EpgEntry>>(new Map());
  // Junto com `agora`, pra calcular a barra de progresso sem outro timer: esta
  // busca já roda a cada 60s, então "agora" (o instante) pode vir do mesmo
  // lugar — sem isso, `Date.now()` teria que ser lido direto no render, o que
  // quebra a pureza (achado real no `LiveChannels.tsx`, mesma ideia aqui).
  const [agoraMs, setAgoraMs] = useState(() => Date.now());
  useEffect(() => {
    if (!listId) return;
    let vivo = true;
    const buscar = () =>
      void rt.epg(listId).nowForList().then((m) => {
        if (vivo) {
          setAgora(m);
          setAgoraMs(Date.now());
        }
      });
    buscar();
    const timer = window.setInterval(buscar, 60_000);
    return () => {
      vivo = false;
      window.clearInterval(timer);
    };
  }, [rt, listId]);

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          position: 'absolute',
          top: 0,
          bottom: 0,
          left: 0,
          width: cssLen('min(24rem, 38vw)'),
          background: 'var(--bg-scrim)',
          padding: 'var(--safe-y) 1rem',
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('0.6rem'),
        }}
      >
        <strong style={{ fontSize: 'var(--fs-section)' }}>{t('nav.live')}</strong>
        <div style={{ flex: 1, minHeight: 0 }}>
          <VirtualGrid<QueueItem>
            focusKey="player-channels-grid"
            // sem `restoreKey`: a posição aqui é sempre a do canal no ar
            items={items}
            columns={1}
            itemHeight={Math.round(rem * 4)}
            rowGap={Math.round(rem * 0.35)}
            colGap={0}
            onItemPress={(_it, i) => onPick(i)}
            renderItem={(it, i, focused) => {
              const epg = agora.get(it.id);
              return (
              <div
                className={gapRowClass}
                style={{
                  height: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  padding: '0 0.8rem',
                  borderRadius: 'var(--radius-sm)',
                  background: focused ? 'var(--bg-raised)' : 'transparent',
                  color: i === currentIndex ? 'var(--accent)' : 'var(--text-primary)',
                  ...gapVar('0.7rem'),
                  ...focusRing(focused),
                }}
              >
                <span
                  style={{
                    width: '3ch',
                    textAlign: 'right',
                    color: 'var(--text-disabled)',
                  }}
                >
                  {it.num ?? ''}
                </span>
                <span
                  style={{
                    flex: 1,
                    minWidth: 0,
                    display: 'flex',
                    flexDirection: 'column',
                    lineHeight: 1.2,
                  }}
                >
                  <span
                    style={{
                      whiteSpace: 'nowrap',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                    }}
                  >
                    {it.title}
                  </span>
                  {epg && (
                    <>
                      <span
                        style={{
                          fontSize: 'var(--fs-meta)',
                          color: 'var(--text-secondary)',
                          whiteSpace: 'nowrap',
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                        }}
                      >
                        {epg.title}
                      </span>
                      {/* progresso do programa no ar — mesma fórmula do
                          `LiveProgress`/`LiveChannels` */}
                      <div
                        style={{
                          marginTop: '0.15rem',
                          height: '0.15rem',
                          borderRadius: '0.1rem',
                          background: 'var(--bg-raised)',
                          overflow: 'hidden',
                        }}
                      >
                        <div
                          style={{
                            width: `${Math.round(Math.min(1, Math.max(0, (agoraMs - epg.start) / Math.max(1, epg.stop - epg.start))) * 100)}%`,
                            height: '100%',
                            background: 'var(--accent)',
                          }}
                        />
                      </div>
                    </>
                  )}
                </span>
              </div>
              );
            }}
          />
        </div>
      </div>
    </FocusContext.Provider>
  );
}
